It's a bit hard to parse with nested pre-processor checks IMO, I'd streamline it a bit:

```suggestion
		pid_t cred_pid;
		{
#if defined(__FreeBSD__)
			struct xucred cred = {};
			socklen_t cred_size = sizeof cred;
			getsockopt(new_fd, SOL_LOCAL, LOCAL_PEERCRED, &cred, &cred_size);
			cred_pid = cred.cr_pid;
#elif defined(__NetBSD__)
			struct sockcred cred = {};
			socklen_t cred_size = sizeof cred;
			getsockopt(new_fd, SOL_LOCAL, LOCAL_PEEREID, &cred, &cred_size);
			cred_pid = cred.sc_pid;
#elif defined(__OpenBSD__)
			struct sockpeercred cred = {};
			socklen_t cred_size = sizeof cred;
			getsockopt(new_fd, SOL_SOCKET, SO_PEERCRED, &cred, &cred_size);
			cred_pid = cred.pid;
#else // Linux.
			struct ucred cred = {};
			socklen_t cred_size = sizeof cred;
			getsockopt(new_fd, SOL_SOCKET, SO_PEERCRED, &cred, &cred_size);
			cred_pid = cred.pid;
#endif
		}
```

Or move that scope I added to a `get_cred_pid()` helper method.

